def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class PointMeta(type):
        def __new__(mcs, name, bases, attrs):
            new_cls = super(PointMeta, mcs).__new__(mcs, name, bases, attrs)
            return new_cls

    class BasePoint(metaclass=PointMeta):
        def __init__(self, **kwargs):
            self.fields = fields
            self.srid_map = srid_map
            for field, value in kwargs.items():
                if field in self.fields:
                    setattr(self, field, value)
                else:
                    raise AttributeError(f"Unknown field {field}")

        def get_srid(self):
            return self.srid_map.get('srid')

        def set_srid(self, srid):
            self.srid_map['srid'] = srid

        def __repr__(self):
            field_strs = []
            for field in self.fields:
                value = getattr(self, field, None)
                field_strs.append(f"{field}={value!r}")
            return f"{self.__class__.__name__}({', '.join(field_strs)})"

    DynamicPoint = PointMeta(name, (BasePoint,), {})
    return DynamicPoint
