        raise ValueError("invalid maxsize")
    if (maxsize is None) or (maxsize > 0):
        _maxsize = maxsize
    else:
        raise ValueError("maxsize must be greater than 0 or None")

    def wrapper(func):
        if hasattr(func, "__wrapped__"):
            raise TypeError("can't cache decorator wrapped functions")

        if maxsize is None:
            return _lru_cache_none(func)
        else:
            return _lru_cache_maxsize(func, maxsize, typed)

    # If called without arguments, e.g. @lru_cache
    if callable(maxsize):
        func = maxsize
        maxsize = 128
        typed = False
        return _lru_cache_maxsize(func, maxsize, typed)

    return wrapper

