    import collections
    from functools import wraps

    def decorator(func):

        class LFUCache:
            def __init__(self, capacity):
                self.capacity = capacity
                self.min_freq = 0
                self.keys = {}  # key -> (value, freq)
                self.cache = collections.defaultdict(collections.OrderedDict)  # freq -> OrderedDict(key -> (key, value))

            def get(self, key):
                if key not in self.keys:
                    return -1
                key_val, f = self.keys[key]
                self.increase_freq(key, f)
                return key_val

            def increase_freq(self, key, f):
                self.cache[f+1][key] = self.cache[f].pop(key)
                if not self.cache[f]:
                    del self.cache[f]
                    if self.min_freq == f:
                        self.min_freq = f + 1
                self.keys[key] = (self.keys[key][0], f+1)

            def put(self, key, value):
                if self.capacity <= 0:
                    return
                if key in self.keys:
                    key_val, f = self.keys[key]
                    self.increase_freq(key, f)
                    self.keys[key] = (value, self.keys[key][1])  # hmm, increase_freq already updated the freq
                    # Actually increase_freq updated items in cache and keys, but we need to update value
                    # Let's fix: when putting existing key, just update value and increase freq
                    # But increase_freq uses self.keys[key] for the value? No, it just moves key between freqs.
                    # Let's restructure: 
                    # When key exists, update its value, then increase freq
                    self.increase_freq(key, f)
                    # But after increase_freq, the value in cache is still old. We need to update it.
                    # This is getting messy. Let's use a simpler approach.
                    pass
                else:
                    if len(self.keys) >= self.capacity:
                        # remove least frequently used
                        min_freq_dict = self.cache[self.min_freq]
                        # remove first item
                        old_key, _ = min_freq_dict.popitem(last=False)
                        del self.keys[old_key]
                    self.min_freq = 1
                    self.keys[key] = (value, 1)
                    self.cache[1][key] = (key, value)

        # The above got complicated. Let's implement a cleaner version.

        keys = {}  # key -> (value, freq)
        freq_use = collections.defaultdict(collections.OrderedDict)  # freq -> OrderedDict(key -> (key, value))
        min_freq = 0

        def get(key):
            if key in keys:
                val, f = keys[key]
                # increase freq
                freq_use[f+1][key] = (key, val)
                del freq_use[f][key]
                if not freq_use[f]:
                    del freq_use[f]
                    if min_freq == f:
                        min_freq = f + 1
                keys[key] = (val, f+1)
                return val
            else:
                return (_KEY_NOT_FOUND := -1)  # or some sentinel

        # This is still messy because of the mutable min_freq in closure.
        # Let's use a list to capture min_freq.

        state = {'min_freq': 0}
        inv_freq = 0  # will not be used

        def inner_lfu_get(key):
            if key in keys:
                val, f = keys[key]
                # add to next freq
                freq_use[f + 1][key] = (key, val)
                # remove from current freq
                del freq_use[f][key]
                if len(freq_use[f]) == 0:
                    del freq_use[f]
                    if state['min_freq'] == f:
                        state['min_freq'] = f + 1
                keys[key] = (val, f + 1)
                return val
            else:
                return None  # sentinel representing not found

        def inner_lfu_put(key, value):
            if key in keys:
                val, f = keys[key]
                # update value and increase freq
                freq_use[f + 1][key] = (key, value)
                del freq_use[f][key]
                if len(freq_use[f]) == 0:
                    del freq_use[f]
                    if state['min_freq'] == f:
                        state['min_freq'] = f + 1
                keys[key] = (value, f + 1)
            else:
                if len(keys) >= maxsize:
                    # remove least frequently used
                    k1, v1 = freq_use[state['min_freq']].popitem(last=False)
                    del keys[k1]
                state['min_freq'] = 1
                keys[key] = (value, 1)
                freq_use[1][key] = (key, value)

        @wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                hashable_args = args
            else:
                hashable_args = args
            # Create a hashable key from args and kwargs
            # Note: for simplicity, we assume args and kwargs are hashable
            try:
                key = (args, tuple(sorted(kwargs.items())))
            except:
                key = (args, tuple(kwargs.items()))
            # Since we can't easily hash non-hashable, let's just use args
            key = args if not kwargs else (args, tuple(sorted(kwargs.items())))

            # For the purpose, let's assume all args are hashable
            if key in keys:
                return inner_lfu_get(key)
            else:
                result = func(*args, **kwargs)
                inner_lfu_put(key, result)
                return result

        return wrapper

    return decorator
