    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                with lock:
                    k = key(self, *args, **kwargs)
                    if k not in cache:
                        cache[k] = func(self, *args, **kwargs)
                    return cache[k]
            else:
                k = key(self, *args, **kwargs)
                if k not in cache:
                    cache[k] = func(self, *args, **kwargs)
                return cache[k]
        return wrapper
