def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Convert to a set of base classes and also track the order they appear
    seen = set()
    ordered_minimal = []

    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            # Check if this class is a subclass of any already included base
            is_subclass_of_existing = False
            for existing in ordered_minimal:
                if isinstance(cls, type) and isinstance(existing, type):
                    try:
                        if issubclass(cls, existing):
                            is_subclass_of_existing = True
                            break
                    except Exception:
                        pass
            if not is_subclass_of_existing:
                # Also check if any existing bases are subclasses of this new one
                # If yes, remove them
                new_ordered = []
                for existing in ordered_minimal:
                    if isinstance(cls, type) and isinstance(existing, type):
                        try:
                            if issubclass(existing, cls):
                                seen.discard(existing)
                                continue
                        except Exception:
                            pass
                    new_ordered.append(existing)
                ordered_minimal = new_ordered
                ordered_minimal.append(cls)

    return ordered_minimal
