def deep_merge_nodes(nodes):
    if not nodes:
        return []

    # Use a dict to group by key
    merged = {}
    order = []  # To maintain the order of keys as they appear

    for key, value in nodes:
        # Use the key's value as a unique identifier
        key_value = key.value if hasattr(key, 'value') else key
        if key_value not in merged:
            merged[key_value] = []
            order.append(key_value)
        merged[key_value].append((key, value))

    result = []
    for key_value in order:
        key_values = merged[key_value]
        if len(key_values) == 1:
            key, value = key_values[0]
            result.append((key, value))
        else:
            # Check if all values are MappingNode
            all_mapping = True
            for _, value in key_values:
                if not hasattr(value, 'tag') or value.tag != 'tag:yaml.org,2002:map':
                    all_mapping = False
                    break

            if all_mapping:
                # Deep merge the mapping nodes
                # Use the first key
                first_key, first_value = key_values[0]
                merged_mapping = {}
                merged_order = []
                for _, value in key_values:
                    for k, v in value.value:
                        k_val = k.value if hasattr(k, 'value') else k
                        if k_val not in merged_mapping:
                            merged_mapping[k_val] = []
                            merged_order.append(k_val)
                        merged_mapping[k_val].append((k, v))

                merged_pairs = []
                for k_val in merged_order:
                    k_v_list = merged_mapping[k_val]
                    if len(k_v_list) == 1:
                        k, v = k_v_list[0]
                        merged_pairs.append((k, v))
                    else:
                        # For simplicity, last wins for non-mapping or if we don't want to recurse
                        # But to be consistent, we could recurse. Let's do last wins for now
                        k, v = k_v_list[-1]
                        merged_pairs.append((k, v))

                from ruamel.yaml.nodes import MappingNode, ScalarNode
                new_value = MappingNode(
                    tag=first_value.tag,
                    value=merged_pairs,
                    flow_style=False,
                    rt=first_value.rt,
                    la=first_value.la
                )
                result.append((first_key, new_value))
            else:
                # Last value wins
                key, value = key_values[-1]
                result.append((key, value))

    return result
