def size_to_bytes(size: str) -> int:
    multipliers = {
        'K': 1000,
        'M': 1000 ** 2,
        'G': 1000 ** 3,
        'T': 1000 ** 4,
    }

    if not size:
        return 0

    # Check if the last character is a known suffix
    if size[-1].upper() in multipliers:
        prefix = size[:-1]
        suffix = size[-1].upper()
        multiplier = multipliers[suffix]
    else:
        prefix = size
        multiplier = 1

    # Convert the prefix part to a float to handle cases like "1.5K"
    try:
        value = float(prefix)
    except ValueError:
        # If it's not a valid number, try to parse it as an integer, otherwise raise
        try:
            value = int(prefix)
        except ValueError:
            return 0

    return int(value * multiplier)

