            filename = line[3:]  # Remove the '!!' prefix and the space
            # Skip directories (they end with /)
            if not filename.endswith('/'):
                ignored_files.append(filename)

    # Remove duplicates, filter only from the ignored list, sort lexicographically
    if ignored:
        ignored_set = set(ignored)
        ignored_files = [f for f in ignored_files if f in ignored_set]

    ignored_files = sorted(set(ignored_files))

    # Return as a comma-separated string
    return ','.join(ignored_files)
