def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import configparser
    import logging
    import os

    configs = {}
    errors = []

    for filename in config_filenames:
        parser = configparser.ConfigParser()
        try:
            parser.read(filename)
        except Exception as e:
            error_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Error loading configuration file: {filename}",
                args=(str(e),),
                exc_info=None
            )
            errors.append(error_record)
            continue

        config_dict = {}
        for section in parser.sections():
            config_dict[section] = dict(parser.items(section))

        if overrides:
            for key, value in overrides.items():
                if key in config_dict and isinstance(config_dict[key], dict):
                    config_dict[key][value[0]] = value[1]
                else:
                    # If override key is not a section key, treat it as a top-level key
                    config_dict[key] = value

        if resolve_env:
            for section, items in config_dict.items():
                for key, value in items.items():
                    if isinstance(value, str):
                        config_dict[section][key] = os.path.expandvars(value)

        configs[filename] = config_dict

    return configs, errors
