def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    _ampm = {'AM': 0, 'PM': 1}
    _tokenconstants = []
    for m in dir(datetime):
        if m[0].upper() == m[0].lower() and m[-1:].isdigit():
            _tokenconstants.append(int(m[-1:]))
        elif m.islower():
            _tokenconstants.append(m)

    if not timestr or type(timestr) not in (six.text_type, str, bytes, io.IOBase, io.TextIOBase):
        raise ParserError("datetime string was None")

    # Pre-preserve AM/PM tokens
    for m in _tokenconstants:
        if m in ('PM', 'AM'):
            _tokenconstants.remove(m)

    # Get all tokens from the string
    tokens = self._extract_tokens(timestr)

    # If AM/PM are in the tokens, we need to replace them
    for i, token in enumerate(tokens):
        if token in ('AM', 'PM'):
            tokens[i] = _ampm[token]

    # If the timezone is ignored or not provided, remove any timezone tokens
    if ignoretz:
        tokens = [x for x in tokens if x not in _tokenconstants or not isinstance(x, tzinfo)]

    # Process tokens to build the datetime
    dt_obj = self._parse_date_and_time(tokens, default, tzinfos)

    # Handle fuzzy parsing
    if kwargs.get('fuzzy_with_tokens', False):
        used_tokens = dt_obj.used_tokens
        remaining_tokens = [token for i, token in enumerate(tokens) if i not in used_tokens]
        return dt_obj.datetime, remaining_tokens

    return dt_obj.datetime

