        if 'resources' in data and 'links' in data.get('resources', []):
            for resource in data['resources']:
                if resource.endswith('/acct/header') or resource.endswith('.json'):
                    for link in data['resources'][0].get('links', []):
                        if link.get('rel') == 'http://diaspora.org/ns/link/bridge':
                            return {
                                'type': 'json',
                                'bridge': link.get('href')
                            }
            # If no bridge link found, return the general webfinger data
            return {
                'type': 'json',
                'data': data
            }
        return {
            'type': 'json',
            'data': data
        }
    except json.JSONDecodeError:
        pass

    # If JSON parsing fails, try to parse as XML (XRD - old Diaspora format)
    try:
        root = ET.fromstring(document)
        # Check if it's an XRD document
        if root.tag.endswith('XRD'):
            results = {}
            # Look for link elements with rel="http://diaspora.org/ns/link/bridge"
            for link in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                rel = link.get('rel', '')
                if rel == 'http://diaspora.org/ns/link/bridge':
                    results['bridge'] = link.get('href')
            # Also look for other relevant properties
            for prop in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property'):
                key = prop.get('name', '')
                value = prop.text
                if key and value:
                    results[key] = value
            return {
                'type': 'xrd',
                'data': results
            }
        return {
            'type': 'xrd',
            'data': {}
        }
    except ET.ParseError:
        pass

    # If both parsing attempts fail, return an empty dict
    return {}

