def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    import xml.etree.ElementTree as ET

    url = f"https://{host}/.well-known/host-meta"
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException:
        return None

    try:
        root = ET.fromstring(response.content)
    except ET.ParseError:
        return None

    # Check if root tag is XRD
    if not root.tag.endswith('XRD'):
        return None

    class XRD:
        def __init__(self, element):
            self._element = element

        @property
        def links(self):
            links = []
            for link in self._element.findall('.//{urn:xmpp:xrd:core:0.1}Link'):
                rel = link.get('rel')
                href = link.get('href')
                template = link.get('template')
                prefix = link.get('prefix')
                alias = link.get('alias')
                target_type = link.get('targetType')
                if rel and href:
                    links.append({
                        'rel': rel,
                        'href': href,
                        'template': template,
                        'prefix': prefix,
                        'alias': alias,
                        'targetType': target_type
                    })
            return links

    return XRD(root)
