def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import os

    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_file}")

    with open(spec_file, 'r') as f:
        spec_data = json.load(f)

    # Flatten the dictionary
    def flatten(d, parent_key=''):
        items = []
        for k, v in d.items():
            new_key = parent_key + '.' + k if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten(v, new_key).items())
            elif isinstance(v, list):
                items.extend(flatten({str(i): item}, new_key).items() if not isinstance(item, dict) else flatten({new_key + '.' + str(i): item}, '').items() for i, item in enumerate(v))
                # More correct approach for lists
                items = []
                for k, v in d.items():
                    new_key = parent_key + '.' + k if parent_key else k
                    if isinstance(v, dict):
                        items.extend(flatten(v, new_key).items())
                    elif isinstance(v, list):
                        # Handle list of dicts or scalars
                        for idx, item in enumerate(v):
                            if isinstance(item, dict):
                                items.extend(flatten(item, f"{new_key}[{idx}]").items())
                            else:
                                items.append((f"{new_key}[{idx}]", item))
                    else:
                        items.append((new_key, v))
                return dict(items)
            else:
                items.append((new_key, v))
        return dict(items)

    # Recorrected flatten function
    def flatten(d, parent_key=''):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten(v, new_key).items())
            elif isinstance(v, list):
                for idx, item in enumerate(v):
                    if isinstance(item, dict):
                        items.extend(flatten(item, f"{new_key}[{idx}]").items())
                    else:
                        items.append((f"{new_key}[{idx}]", item))
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten(spec_data)
